func (s *orderServer) PlaceOrder(ctx context.Context, req *orders.PlaceOrderRequest) (
    *orders.OrderConfirmation, error) {
    order, err := domain.CreateOrder(req.Customer, req.Lines)   // fine-grained model
    if err != nil {
        return nil, status.Error(codes.InvalidArgument, err.Error())
    }
    return toConfirmation(order, s.pricing.Price(order)), nil   // transfer object
}
